"use client";

import { useState } from "react";
import { useProducts } from "@/features/products/useProducts";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Copy, Check } from "lucide-react";
import { toast } from "sonner";
import { useAuth } from "@/contexts/AuthContext";

const WIDGET_CDN_URL = "https://cdn.wabisabi.studio/atelier/widget.js";

export default function InstallPage() {
  const { shopId } = useAuth();
  const { data: products = [], isLoading } = useProducts();
  const [selectedProductId, setSelectedProductId] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  const selectedProduct = selectedProductId ? products.find((p) => p.id === selectedProductId) : null;

  const generateSnippet = (productId?: string) => {
    const attributes: string[] = [`data-atelier-shop-id="${shopId}"`];
    
    if (productId) {
      attributes.push(`data-atelier-product-id="${productId}"`);
    }

    return `<div
  ${attributes.join("\n  ")}>
</div>
<script async src="${WIDGET_CDN_URL}"></script>`;
  };

  const snippet = generateSnippet(selectedProductId ?? undefined);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(snippet);
      setCopied(true);
      toast.success("スニペットをコピーしました");
      setTimeout(() => setCopied(false), 2000);
    } catch (error) {
      toast.error("コピーに失敗しました");
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-gray-500">読み込み中...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-semibold">埋め込みスニペット</h1>
        <p className="text-gray-600 mt-2">
          商品ページに埋め込むためのHTMLスニペットを生成します
        </p>
      </div>

      <div className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="product">商品を選択（任意）</Label>
          <Select
            value={selectedProductId || "none"}
            onValueChange={(value) => setSelectedProductId(value === "none" ? null : value)}
          >
            <SelectTrigger id="product">
              <SelectValue placeholder="商品を選択（任意）" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="none">商品を指定しない</SelectItem>
              {products.map((product) => (
                <SelectItem key={product.id} value={product.id}>
                  {product.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <p className="text-sm text-gray-500">
            商品を選択しない場合、ページから自動的に商品IDを取得します
          </p>
        </div>

        {selectedProduct && (
          <div className="p-4 bg-gray-50 rounded-md">
            <p className="text-sm font-medium">選択中の商品</p>
            <p className="text-sm text-gray-600">{selectedProduct.name}</p>
            {selectedProduct.sku && (
              <p className="text-sm text-gray-600">SKU: {selectedProduct.sku}</p>
            )}
          </div>
        )}

          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Label>埋め込みスニペット</Label>
              <Button
                variant="outline"
                size="sm"
                onClick={handleCopy}
                className="gap-2"
              >
                {copied ? (
                  <>
                    <Check className="h-4 w-4" />
                    コピーしました
                  </>
                ) : (
                  <>
                    <Copy className="h-4 w-4" />
                    コピー
                  </>
                )}
              </Button>
            </div>
            <div className="relative">
              <textarea
                value={snippet}
                readOnly
                className="w-full p-3 border rounded-md font-mono text-sm min-h-[100px] resize-none bg-gray-50"
              />
            </div>
          </div>

        <div className="p-4 bg-blue-50 rounded-md">
          <p className="text-sm font-medium text-blue-900 mb-2">
            使用方法
          </p>
          <ol className="text-sm text-blue-800 space-y-1 list-decimal list-inside">
            <li>上記のスニペットをコピーします</li>
            <li>商品ページのHTMLに貼り付けます</li>
            <li>
              商品IDが指定されていない場合、以下の属性で商品を識別できます:
              <ul className="list-disc list-inside ml-4 mt-1">
                <li>data-atelier-sku: SKUで識別</li>
                <li>data-atelier-handle: Handleで識別</li>
                <li>data-atelier-url: URLで識別</li>
              </ul>
            </li>
          </ol>
        </div>
      </div>
    </div>
  );
}
